import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -res : res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int[] head = new int[n + 1];
        int[] to = new int[2 * m + 2];
        int[] next = new int[2 * m + 2];
        int[] deg = new int[n + 1];
        int edgeCount = 1;

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();

            deg[u]++;
            deg[v]++;

            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        boolean[] visited = new boolean[n + 1];
        int[] comp = new int[n + 1];
        boolean[] isNeighbor = new boolean[n + 1];

        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                int compSize = 0;
                long totalDegree = 0;

                int headQueue = 0, tailQueue = 0;
                comp[tailQueue++] = i;
                visited[i] = true;

                while (headQueue < tailQueue) {
                    int u = comp[headQueue++];
                    compSize++;
                    totalDegree += deg[u];

                    for (int e = head[u]; e != 0; e = next[e]) {
                        int v = to[e];
                        if (!visited[v]) {
                            visited[v] = true;
                            comp[tailQueue++] = v;
                        }
                    }
                }

                long numEdgesInComp = totalDegree / 2;
                long maxEdges = (long) compSize * (compSize - 1) / 2;

                if (numEdgesInComp < maxEdges) {
                    // This component is not a clique, so there exists at least one pair
                    // Find a vertex with degree < compSize - 1
                    int targetNode = -1;
                    for (int j = 0; j < compSize; j++) {
                        int u = comp[j];
                        if (deg[u] < compSize - 1) {
                            targetNode = u;
                            break;
                        }
                    }

                    // Mark neighbors of targetNode
                    for (int e = head[targetNode]; e != 0; e = next[e]) {
                        isNeighbor[to[e]] = true;
                    }

                    // Find a node in the same component that is not targetNode and not a neighbor
                    int nonNeighbor = -1;
                    for (int j = 0; j < compSize; j++) {
                        int v = comp[j];
                        if (v != targetNode && !isNeighbor[v]) {
                            nonNeighbor = v;
                            break;
                        }
                    }

                    System.out.println(targetNode + " " + nonNeighbor);
                    return;
                }
            }
        }

        System.out.println("-1");
    }
}
